<?php
declare(strict_types=1);require __DIR__.'/workflow-core.php';trackingHeaders();header('Content-Type: application/json; charset=utf-8');
if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);exit;}
try{$input=json_decode((string)file_get_contents('php://input'),true);$token=(string)($input['token']??'');if(($input['accept']??false)!==true)throw new InvalidArgumentException('Confirm proposal acceptance.');$found=workflowCustomerRecord($token);trackingLocked(function()use($found){$record=workflowProject(trackingRead($found['id']));if(!$record['proposal_sent_at'])throw new InvalidArgumentException('Proposal unavailable.');if(!$record['proposal_accepted_at']){$record['proposal_accepted_at']=gmdate('c');$record['stage']='Creation';$record['update']='The proposal was accepted. Creation is now in progress.';$record['next_step']='No action is required right now. AOR will share the next update.';$record['updated_at']=gmdate('c');$record['revision']=bin2hex(random_bytes(16));workflowActivity($record,'proposal_accepted','Accepted through private tracking link.');trackingWrite($found['id'],$record);}});echo json_encode(['ok'=>true]);}catch(OutOfBoundsException $e){http_response_code(404);echo json_encode(['error'=>'Link unavailable or expired.']);}catch(Throwable $e){http_response_code(422);echo json_encode(['error'=>$e->getMessage()]);}
